@Repository
public interface TransportadoraRepository extends JpaRepository<TransportadoraEntity, Long> {
    boolean existsByCnpj(String cnpj);
}

@Service
public class TransportadoraCadastroService {

    private final TransportadoraRepository repository;

    public TransportadoraCadastroService(TransportadoraRepository repository) {
        this.repository = repository;
    }

    @Transactional(rollbackFor = BusinessException.class)
    public Long cadastrar(TransportadoraCadastroDTO dto) {
        if (repository.existsByCnpj(dto.cnpj())) {
            throw new TransportadoraDuplicadaException(dto.cnpj());
        }
        TransportadoraEntity entity = new TransportadoraEntity(dto.cnpj(), dto.nome(), "A");
        try {
            return repository.save(entity).getCodigo();
        } catch (DataIntegrityViolationException e) {
            throw new TransportadoraDuplicadaException(dto.cnpj());
        }
    }
}

public class TransportadoraDuplicadaException extends BusinessException {
    public TransportadoraDuplicadaException(String cnpj) {
        super("Transportadora com CNPJ " + cnpj + " ja cadastrada.");
    }
}

