public record CargaValidacaoDTO(Long numeroViagem, BigDecimal valor, String tipoCarga) {}

@Repository
public interface CargaHeaderRepository extends JpaRepository<CargaHeaderEntity, Long> {
    boolean existsByNumeroViagemAndSeguroContratadoTrue(Long numeroViagem);
}

@Service
public class CargaValidacaoService {

    private static final BigDecimal LIMITE_ESCOLTA = new BigDecimal("100000");
    private static final String TIPO_ESCOLTA = "EX";

    private final CargaHeaderRepository cargaHeaderRepository;

    public CargaValidacaoService(CargaHeaderRepository cargaHeaderRepository) {
        this.cargaHeaderRepository = cargaHeaderRepository;
    }

    @Transactional(readOnly = true)
    public void validar(CargaValidacaoDTO dto) {
        if (exigeEscolta(dto) && !TIPO_ESCOLTA.equals(dto.tipoCarga())) {
            throw new EscoltaObrigatoriaException(dto.numeroViagem());
        }
        if (!cargaHeaderRepository.existsByNumeroViagemAndSeguroContratadoTrue(dto.numeroViagem())) {
            throw new SeguroCargaObrigatorioException(dto.numeroViagem());
        }
    }

    private boolean exigeEscolta(CargaValidacaoDTO dto) {
        return dto.valor().compareTo(LIMITE_ESCOLTA) > 0;
    }
}

public class EscoltaObrigatoriaException extends BusinessException {
    public EscoltaObrigatoriaException(Long numeroViagem) {
        super("Viagem " + numeroViagem + " exige escolta para cargas acima do limite.");
    }
}

public class SeguroCargaObrigatorioException extends BusinessException {
    public SeguroCargaObrigatorioException(Long numeroViagem) {
        super("Viagem " + numeroViagem + " sem seguro contratado.");
    }
}

