public class CargaConfirmacaoService {

    private final CargaHeaderRepository cargaHeaderRepository;
    private final CargaDetailRepository cargaDetailRepository;

    public CargaConfirmacaoService(CargaHeaderRepository cargaHeaderRepository,
                                   CargaDetailRepository cargaDetailRepository) {
        this.cargaHeaderRepository = cargaHeaderRepository;
        this.cargaDetailRepository = cargaDetailRepository;
    }

    @Transactional(rollbackFor = Exception.class)
