public record SolicitacaoManutencaoDTO(Long id, String status, String usuarioAprovador) {}

public enum StatusSolicitacao {
    PENDENTE("P"), APROVADA("A"), REPROVADA("R"), CANCELADA("C");

    private final String codigo;
    StatusSolicitacao(String codigo) { this.codigo = codigo; }
    public String getCodigo() { return codigo; }

    public static StatusSolicitacao fromCodigo(String codigo) {
        for (StatusSolicitacao s : values()) {
            if (s.codigo.equals(codigo)) return s;
        }
        throw new StatusSolicitacaoInvalidoException(codigo);
    }
}

@Repository
public interface SolicitacaoManutencaoRepository extends JpaRepository<SolicitacaoManutencaoEntity, Long> {}

@Service
public class SolicitacaoManutencaoService {

    private final SolicitacaoManutencaoRepository repository;

    public SolicitacaoManutencaoService(SolicitacaoManutencaoRepository repository) {
        this.repository = repository;
    }

    @Transactional
    public void aprovar(Long id, String usuario) {
        SolicitacaoManutencaoEntity entity = repository.findById(id)
            .orElseThrow(() -> new SolicitacaoNaoEncontradaException(id));

        if (entity.getStatus() != StatusSolicitacao.PENDENTE) {
            throw new TransicaoStatusInvalidaException(entity.getStatus(), StatusSolicitacao.APROVADA);
        }

        entity.aprovar(usuario);
    }
}

public class TransicaoStatusInvalidaException extends BusinessException {
    public TransicaoStatusInvalidaException(StatusSolicitacao atual, StatusSolicitacao destino) {
        super("Transicao invalida de " + atual + " para " + destino + ".");
    }
}

@Service
public class SolicitacaoCancelamentoService {

    private final SolicitacaoManutencaoRepository repository;

    public SolicitacaoCancelamentoService(SolicitacaoManutencaoRepository repository) {
        this.repository = repository;
    }

    @Transactional
    public void cancelar(Long id) {
        SolicitacaoManutencaoEntity entity = repository.findById(id)
            .orElseThrow(() -> new SolicitacaoNaoEncontradaException(id));

        StatusSolicitacao status = entity.getStatus();
        if (status == StatusSolicitacao.APROVADA) {
            throw new SolicitacaoJaAprovadaException(id);
        }
        if (status == StatusSolicitacao.CANCELADA) {
            throw new SolicitacaoJaCanceladaException(id);
        }

        entity.cancelar();
    }
}

public class SolicitacaoJaAprovadaException extends BusinessException {
    public SolicitacaoJaAprovadaException(Long id) {
        super("Solicitacao " + id + " ja esta APROVADA e nao pode ser cancelada.");
    }
}

public class SolicitacaoJaCanceladaException extends BusinessException {
    public SolicitacaoJaCanceladaException(Long id) {
        super("Solicitacao " + id + " ja esta CANCELADA.");
    }
}
